// Receives N items (1 per lesson with Status_Quiz=a_produire)
// Groups them by Cours+Module to produce 1 item per module with lessons listed
const allItems = $input.all().map(i => i.json);

const modules = {};
for (const row of allItems) {
  const key = (row.Cours || '') + '|||' + (row.Module || '');
  if (!modules[key]) {
    modules[key] = {
      course_title: row.Cours || '',
      module_raw: row.Module || '',
      lessons: [],
      ids: []
    };
  }
  modules[key].lessons.push({
    lecon: row.Lecon || '',
    type: row.Type || '',
    duree: row.Duree || ''
  });
  modules[key].ids.push(row.id);
}

const results = [];
for (const [key, mod] of Object.entries(modules)) {
  // Parse "M1: Titre du module"
  const moduleMatch = mod.module_raw.match(/^M(\d+):\s*(.+)$/);
  const moduleNumber = moduleMatch ? parseInt(moduleMatch[1]) : 1;
  const moduleTitle = moduleMatch ? moduleMatch[2].trim() : mod.module_raw;

  const lessonsSummary = mod.lessons.map(l => l.lecon + ' (' + l.type + ', ' + l.duree + ')').join(' | ');

  results.push({
    json: {
      course_title: mod.course_title,
      module_title: moduleTitle,
      module_number: moduleNumber,
      module_raw: mod.module_raw,
      lessons_summary: lessonsSummary,
      lessons_count: mod.lessons.length,
      ids: mod.ids
    }
  });
}

return results.length ? results : [{ json: { _empty: true } }];

// runOnceForEachItem — resilient parse (never crashes, skips bad items)
const response = $input.item.json;
const allModules = $('Filter — Modules valides').all();
const moduleData = allModules[$itemIndex]?.json || {};

// Extract raw text
let rawText = '';
if (response.content?.parts) {
  rawText = response.content.parts.map(p => p.text || '').join('');
} else if (response.quiz) {
  return { json: { course_title: moduleData.course_title || '', module_title: moduleData.module_title || '', module_number: moduleData.module_number || 0, module_raw: moduleData.module_raw || '', questions_count: (response.quiz.questions || []).length, quiz_title: response.quiz.title || 'Quiz', exercise_title: (response.practical_exercise || {}).title || '', ids: moduleData.ids || [], _parse_failed: false } };
} else if (typeof response === 'string') {
  rawText = response;
} else {
  rawText = JSON.stringify(response);
}

// Clean
let cleaned = rawText.trim();
cleaned = cleaned.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();
cleaned = cleaned.replace(/,\s*([\}\]])/g, '$1');

// Try parse strategies
let parsed = null;

// Strategy 1: direct parse
try { parsed = JSON.parse(cleaned); } catch(e) {}

// Strategy 2: regex extract first {...} block + cleanup
if (!parsed) {
  try {
    const match = cleaned.match(/\{[\s\S]+\}/);
    if (match) {
      let block = match[0].replace(/,\s*([\}\]])/g, '$1');
      parsed = JSON.parse(block);
    }
  } catch(e) {}
}

// Strategy 3: try to find "quiz" key and extract from there
if (!parsed) {
  try {
    const qStart = cleaned.indexOf('"quiz"');
    if (qStart > 0) {
      const blockStart = cleaned.lastIndexOf('{', qStart);
      if (blockStart >= 0) {
        let block = cleaned.substring(blockStart);
        block = block.replace(/,\s*([\}\]])/g, '$1');
        // Find matching end
        let depth = 0;
        for (let i = 0; i < block.length; i++) {
          if (block[i] === '{') depth++;
          if (block[i] === '}') { depth--; if (depth === 0) { block = block.substring(0, i+1); break; } }
        }
        parsed = JSON.parse(block);
      }
    }
  } catch(e) {}
}

// GRACEFUL FALLBACK — don't crash, return empty result
if (!parsed) {
  return {
    json: {
      course_title: moduleData.course_title || '',
      module_title: moduleData.module_title || '',
      module_number: moduleData.module_number || 0,
      module_raw: moduleData.module_raw || '',
      questions_count: 0,
      quiz_title: 'Quiz — echec parsing',
      exercise_title: '',
      ids: [],
      _parse_failed: true,
      _error: 'JSON parse failed after all strategies. Length: ' + rawText.length
    }
  };
}

const quiz = parsed.quiz || {};
const exercise = parsed.practical_exercise || {};

return {
  json: {
    course_title: moduleData.course_title || '',
    module_title: moduleData.module_title || '',
    module_number: moduleData.module_number || 0,
    module_raw: moduleData.module_raw || '',
    questions_count: (quiz.questions || []).length,
    quiz_title: quiz.title || 'Quiz — Module ' + (moduleData.module_number || '?'),
    exercise_title: exercise.title || '',
    ids: moduleData.ids || [],
    _parse_failed: false
  }
};

// runOnceForAllItems — flatten all ids from all modules into individual update items
const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const ids = item.json.ids || [];
  const failed = item.json._parse_failed === true;

  // Skip modules that failed parsing (no ids)
  if (failed || ids.length === 0) continue;

  for (const rn of ids) {
    results.push({
      json: {
        id: rn,
        Status_Quiz: 'produit'
      }
    });
  }
}

// If no rows to update, return a dummy item that won't match anything
if (results.length === 0) {
  return [{ json: { id: -1, Status_Quiz: 'skip', _no_updates: true } }];
}

return results;

// Log the raw Gemini response for debugging
const response = $input.item.json;

let rawText = '';
if (response.content?.parts) {
  rawText = response.content.parts.map(p => p.text || '').join('');
} else if (typeof response === 'string') {
  rawText = response;
} else {
  rawText = JSON.stringify(response, null, 2);
}

console.log('=== GEMINI RAW RESPONSE ===');
console.log('Length:', rawText.length, 'characters');
console.log('First 500 chars:', rawText.substring(0, 500));
console.log('Last 500 chars:', rawText.substring(rawText.length - 500));

// Check for common JSON issues
const hasCodeFence = rawText.includes('```');
const hasTrailingComma = /,\s*[\}\]]/.test(rawText);
const startsWithBrace = rawText.trim().startsWith('{');
const endsWithBrace = rawText.trim().endsWith('}');

console.log('Has code fence:', hasCodeFence);
console.log('Has trailing commas:', hasTrailingComma);
console.log('Starts with {:', startsWithBrace);
console.log('Ends with }:', endsWithBrace);

// Pass through the original response
return { json: response };

